import{_ as t,a as o,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Delete Locale","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Delete Locale","description":"Remove a locale from the store.","query":"mutation Delete($input: deleteAdminSettingsLocaleInput!) {\\n  deleteAdminSettingsLocale(input: $input) {\\n    adminSettingsLocale {\\n      _id\\n      code\\n      name\\n      direction\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/locales/47\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsLocale\\": {\\n      \\"adminSettingsLocale\\": {\\n        \\"_id\\": 47,\\n        \\"code\\": \\"fr\\",\\n        \\"name\\": \\"French\\",\\n        \\"direction\\": \\"ltr\\",\\n        \\"message\\": \\"Locale deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/locales/delete.md","filePath":"api/graphql-api/admin/settings/locales/delete.md","lastUpdated":1787725411000}'),l={name:"api/graphql-api/admin/settings/locales/delete.md"};function d(s,e,i,r,c,h){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="delete-locale" tabindex="-1">Delete Locale <a class="header-anchor" href="#delete-locale" aria-label="Permalink to &quot;Delete Locale&quot;">​</a></h1><p>Permanently removes a locale, subject to the guards below.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsLocale</code></td><td>Mutation</td><td>Delete a locale by id</td></tr></tbody></table><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p>The delete is refused (returns an <code>errors[]</code> entry, no record removed) when:</p><ul><li>It is the <strong>only remaining locale</strong> in the store.</li><li>The locale is set as the <strong>default locale of one or more channels</strong>. For example: <code>&quot;This locale is the default locale of one or more channels and cannot be deleted.&quot;</code> Re-point the channel(s) to another default locale first.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The returned node is an in-memory snapshot of the just-deleted record — its scalar fields (<code>_id</code>, <code>code</code>, <code>name</code>, <code>direction</code>) still resolve so you can confirm what was removed.</li><li>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Locale deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a failed delete returns a top-level <code>errors[]</code> entry instead.</li><li>Do <strong>not</strong> select the node&#39;s IRI <code>id</code> field on this mutation — the IRI cannot be generated for a deleted record and the field resolves with an <code>errors[]</code> entry. Select <code>_id</code> instead, as shown.</li><li>Use the <a href="./list.html"><code>adminSettingsLocales</code></a> query to discover valid ids.</li></ul><p>Permissions: <code>settings.locales.delete</code>. See the <a href="./">Locales overview</a> for behaviour.</p>',10)]))}const p=t(l,[["render",d]]);export{m as __pageData,p as default};
